from decimal import Decimal, ROUND_HALF_UP, InvalidOperation, localcontext
import datetime
import re

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_CENT = Decimal("0.00")
_FOURDP = Decimal("0.0000")

def _places(d):
    e = d.as_tuple().exponent
    if isinstance(e, str):
        return 0
    if e >= 0:
        return 0
    return -e

def fifo_report(trades):
    if not isinstance(trades, list):
        raise ValueError("trades must be a list")
    lots_qty = []
    lots_cost = []
    sales = []
    with localcontext() as ctx:
        ctx.prec = 80
        for trade in trades:
            if not isinstance(trade, dict):
                raise ValueError("trade must be a dict")
            if "date" not in trade or "side" not in trade or "quantity" not in trade or "price" not in trade:
                raise ValueError("missing required key")
            date_raw = trade["date"]
            side_raw = trade["side"]
            qty_raw = trade["quantity"]
            price_raw = trade["price"]
            if "fee" in trade:
                fee_raw = trade["fee"]
            else:
                fee_raw = "0.00"
            if not isinstance(date_raw, str):
                raise ValueError("bad date")
            if _DATE_RE.fullmatch(date_raw) is None:
                raise ValueError("bad date")
            try:
                y = int(date_raw[0:4])
                m = int(date_raw[5:7])
                d = int(date_raw[8:10])
                datetime.date(y, m, d)
            except ValueError:
                raise ValueError("bad date")
            if side_raw != "BUY" and side_raw != "SELL":
                raise ValueError("bad side")
            if type(qty_raw) is not int:
                raise ValueError("bad quantity")
            if qty_raw <= 0:
                raise ValueError("bad quantity")
            if not isinstance(price_raw, str):
                raise ValueError("bad price")
            try:
                price = Decimal(price_raw)
            except Exception:
                raise ValueError("bad price")
            if not price.is_finite():
                raise ValueError("bad price")
            if price <= 0:
                raise ValueError("bad price")
            if _places(price) > 4:
                raise ValueError("bad price")
            if not isinstance(fee_raw, str):
                raise ValueError("bad fee")
            try:
                fee = Decimal(fee_raw)
            except Exception:
                raise ValueError("bad fee")
            if not fee.is_finite():
                raise ValueError("bad fee")
            if fee < 0:
                raise ValueError("bad fee")
            if _places(fee) > 2:
                raise ValueError("bad fee")
            if side_raw == "BUY":
                total = Decimal(qty_raw) * price + fee
                lots_qty.append(qty_raw)
                lots_cost.append(total)
            else:
                inv = 0
                for q in lots_qty:
                    inv += q
                if inv < qty_raw:
                    raise ValueError("insufficient inventory")
                need = qty_raw
                consumed = Decimal(0)
                idx = 0
                while need > 0:
                    q = lots_qty[idx]
                    c = lots_cost[idx]
                    if q <= 0:
                        idx += 1
                        continue
                    if q <= need:
                        taken = q
                    else:
                        taken = need
                    part = c * Decimal(taken) / Decimal(q)
                    consumed = consumed + part
                    lots_cost[idx] = c - part
                    lots_qty[idx] = q - taken
                    need -= taken
                    if lots_qty[idx] == 0:
                        idx += 1
                    elif need > 0 and q == taken:
                        idx += 1
                proceeds_exact = Decimal(qty_raw) * price - fee
                proceeds_q = proceeds_exact.quantize(_CENT, rounding=ROUND_HALF_UP)
                cost_q = consumed.quantize(_CENT, rounding=ROUND_HALF_UP)
                realized_exact = proceeds_exact - consumed
                realized_q = realized_exact.quantize(_CENT, rounding=ROUND_HALF_UP)
                sales.append({"date": date_raw, "quantity": qty_raw, "proceeds": proceeds_q, "cost": cost_q, "realized": realized_q})
        acc = Decimal("0.00")
        for s in sales:
            acc = acc + s["realized"]
        total_realized = acc.quantize(_CENT, rounding=ROUND_HALF_UP)
        remaining = []
        inv_qty = 0
        for q, c in zip(lots_qty, lots_cost):
            if q > 0:
                inv_qty += q
                tc = c.quantize(_CENT, rounding=ROUND_HALF_UP)
                uc = (c / Decimal(q)).quantize(_FOURDP, rounding=ROUND_HALF_UP)
                remaining.append({"quantity": q, "unit_cost": uc, "total_cost": tc})
    return {"sales": sales, "total_realized": total_realized, "remaining": remaining, "inventory_quantity": inv_qty}
